style.css:
@-moz-document domain("youtube.com") {
/* 1. KEEP THE GRADIENT TIMELINE LINE */
    .ytp-play-progress.ytp-swatch-background-color {
        background: linear-gradient(to right, #bd93f9, #ff79c6) !important;
    }

    /* 2. TRANSFORM THE KNOB INTO A CUSTOM CHARACTER */
    .ytp-scrubber-button.ytp-swatch-background-color {
        /* REPLACE THE URL BELOW with your character image (GIF or PNG) */
        background-image: url("https://i.ibb.co/LbCJCcq/f8b53abc3a319056c932b0f93fb9b2f1.png") !important; 
        
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center bottom !important;
        background-color: transparent !important;
        
        /* Hides the default red/yellow circle container */
        border: none !important;
        box-shadow: none !important;
        border-radius: 0 !important;
        
        /* Adjust size of your character here */
        width: 35px !important;
        height: 35px !important;
        
        /* Positions the character perfectly on top of the line instead of inside it */
        transform: translate(-50%, -30%) !important; 
    }

    /* Keeps the image looking sharp when hovering over the progress bar */
    .ytp-scrubber-container:hover .ytp-scrubber-button {
        transform: translate(-50%, -30%) scale(1.1) !important;
    }
}
